// Normalize Jobs - map the official Upwork GraphQL response into the flat
// shape the scorer expects. Field names follow the public marketplace job
// posting search schema; adjust here (not in the scorer) if Upwork renames a
// field. Nothing is written back to Upwork.
const cfg = $('Caps Preflight').first().json;
const response = $input.first().json;
const edges =
  (((response.data || {}).marketplaceJobPostingsSearch || {}).edges) || [];

const jobs = edges.map((edge) => {
  const n = edge.node || {};
  const client = n.client || {};
  const amount = (n.amount || {}).rawValue;
  const hourlyMin = ((n.hourlyBudgetMin || {}).rawValue);
  const hourlyMax = ((n.hourlyBudgetMax || {}).rawValue);
  const ciphertext = n.ciphertext || n.id || '';
  return {
    id: n.id || ciphertext,
    title: n.title || '',
    description: n.description || '',
    skills: (n.skills || []).map((s) => (s && s.name ? s.name : String(s))),
    job_type: String(n.job && n.job.contractTerms
      && n.job.contractTerms.contractType === 'HOURLY' ? 'hourly' : 'fixed'),
    budget: amount === undefined || amount === null ? null : Number(amount),
    hourly_min: hourlyMin === undefined || hourlyMin === null ? null : Number(hourlyMin),
    hourly_max: hourlyMax === undefined || hourlyMax === null ? null : Number(hourlyMax),
    proposals: n.totalApplicants === undefined ? null : Number(n.totalApplicants),
    posted_at: n.publishedDateTime || n.createdDateTime || null,
    url: ciphertext ? 'https://www.upwork.com/jobs/' + ciphertext : null,
    client: {
      country: (client.location || {}).country || null,
      hire_rate: client.totalHires && client.totalPostedJobs
        ? client.totalHires / client.totalPostedJobs : null,
      total_spend: ((client.totalSpent || {}).rawValue) === undefined
        ? null : Number((client.totalSpent || {}).rawValue),
      payment_verified: client.verificationStatus === undefined
        ? null : client.verificationStatus === 'VERIFIED',
      jobs_posted: client.totalPostedJobs === undefined
        ? null : Number(client.totalPostedJobs),
    },
  };
});

return jobs.map((job) => ({ json: { job, rubric: cfg.rubric, caps: cfg.caps } }));

/**
 * JS twin of scoring/score.py.
 *
 * This exact file is embedded into the "Score Jobs" Code node of
 * workflows/upwork-job-radar.json by scripts/build_workflow.py. Do not edit
 * the copy inside the workflow JSON - edit this file and rebuild.
 *
 * tests/test_parity.py runs this under Node against the same fixtures as the
 * Python scorer and fails if a single number or reason string differs, so the
 * logic you review in Python is provably the logic n8n runs.
 *
 * Read-only: this file scores jobs. It never calls Upwork.
 */

const DEFAULT_RUBRIC = {
  alert_threshold: 70,
  unknown_client_policy: "neutral",
  weights: {
    client_country: 10,
    hire_rate: 15,
    client_spend: 12,
    payment_verified: 8,
    budget: 20,
    proposals: 15,
    keywords: 12,
    freshness: 8,
  },
  client_country: {
    allowlist: [
      "US",
      "CA",
      "GB",
      "AU",
      "NZ",
      "IE",
      "DE",
      "NL",
      "SE",
      "NO",
      "DK",
      "FI",
      "CH",
      "AT",
      "BE",
      "FR",
      "SG",
      "AE",
    ],
    blocklist: [],
    hard_gate: true,
  },
  hire_rate: { target: 0.6, hard_fail_below: 0.4, hard_gate: true },
  client_spend: { target_usd: 10000, hard_fail_below_usd: 0, hard_gate: false },
  payment_verified: { required: true },
  budget: {
    fixed_floor_usd: 500,
    fixed_target_usd: 3000,
    hourly_floor_usd: 35,
    hourly_target_usd: 75,
    hard_gate: true,
    missing_budget_policy: "neutral",
  },
  proposals: { ideal_max: 5, zero_at: 50 },
  keywords: {
    must_have_any: [],
    must_not_have: ["unpaid", "revenue share only", "equity only", "no budget"],
    bonus: [
      "n8n",
      "automation",
      "workflow",
      "api integration",
      "wordpress",
      "shopify",
      "openai",
      "anthropic",
      "webhook",
    ],
    hard_gate: true,
  },
  freshness: { fresh_hours: 2, stale_hours: 48 },
};

function roundHalfUp(value, digits) {
  const d = digits || 0;
  const factor = Math.pow(10, d);
  const scaled = Math.floor(Math.abs(value) * factor + 0.5) / factor;
  return value < 0 ? -scaled : scaled;
}

function mergeRubric(base, override) {
  const out = {};
  Object.keys(base).forEach((k) => {
    const v = base[k];
    out[k] =
      v && typeof v === "object" && !Array.isArray(v)
        ? Object.assign({}, v)
        : v;
  });
  if (!override) return out;
  Object.keys(override).forEach((k) => {
    const v = override[k];
    if (
      v &&
      typeof v === "object" &&
      !Array.isArray(v) &&
      out[k] &&
      typeof out[k] === "object" &&
      !Array.isArray(out[k])
    ) {
      out[k] = Object.assign({}, out[k], v);
    } else {
      out[k] = v;
    }
  });
  return out;
}

function clamp(value, low, high) {
  const lo = low === undefined ? 0 : low;
  const hi = high === undefined ? 1 : high;
  return Math.max(lo, Math.min(hi, value));
}

function ramp(value, zeroAt, fullAt) {
  if (fullAt === zeroAt) return value >= fullAt ? 1 : 0;
  return clamp((value - zeroAt) / (fullAt - zeroAt));
}

function parseTs(value) {
  if (value === null || value === undefined) return null;
  if (value instanceof Date) return isNaN(value.getTime()) ? null : value;
  let text = String(value).trim();
  // Match Python's fromisoformat + "naive means UTC" behaviour.
  if (!/(Z|[+-]\d{2}:?\d{2})$/.test(text)) text += "Z";
  const ms = Date.parse(text);
  return isNaN(ms) ? null : new Date(ms);
}

function haystack(job) {
  const skills = (job.skills || []).map(String).join(" ");
  return [String(job.title || ""), String(job.description || ""), skills]
    .join(" ")
    .toLowerCase();
}

function pct(value) {
  if (value === null || value === undefined) return null;
  const number = Number(value);
  if (isNaN(number)) return null;
  return number > 1 ? number / 100 : number;
}

function money(value) {
  const n = Math.trunc(roundHalfUp(value, 0));
  return String(n).replace(/\B(?=(\d{3})+(?!\d))/g, ",");
}

function pctStr(value) {
  return money(value * 100) + "%";
}

function hours(value) {
  return roundHalfUp(value, 1).toFixed(1);
}

function crit(key, earned, maximum, reason) {
  return {
    key: key,
    earned: roundHalfUp(earned, 2),
    maximum: roundHalfUp(maximum, 2),
    reason: reason,
  };
}

// -- criteria ---------------------------------------------------------------

function cCountry(job, rub, weight, disq) {
  const cfg = rub.client_country;
  const raw = (job.client || {}).country;
  const code = raw ? String(raw).toUpperCase() : null;
  const allow = (cfg.allowlist || []).map((c) => String(c).toUpperCase());
  const block = (cfg.blocklist || []).map((c) => String(c).toUpperCase());
  if (code === null) {
    return crit(
      "client_country",
      weight * 0.5,
      weight,
      "client country unknown - half credit",
    );
  }
  if (block.indexOf(code) !== -1) {
    if (cfg.hard_gate)
      disq.push("client country " + code + " is on the blocklist");
    return crit("client_country", 0, weight, code + " is blocklisted");
  }
  if (allow.length && allow.indexOf(code) === -1) {
    if (cfg.hard_gate)
      disq.push("client country " + code + " is not on the allowlist");
    return crit("client_country", 0, weight, code + " is not on the allowlist");
  }
  return crit("client_country", weight, weight, code + " allowed");
}

function cHireRate(job, rub, weight, disq) {
  const cfg = rub.hire_rate;
  const rate = pct((job.client || {}).hire_rate);
  if (rate === null) {
    const policy = rub.unknown_client_policy || "neutral";
    if (policy === "disqualify") {
      disq.push("client has no hire-rate history");
      return crit("hire_rate", 0, weight, "no hire history");
    }
    const share = policy === "penalize" ? 0 : 0.5;
    return crit(
      "hire_rate",
      weight * share,
      weight,
      "no hire history - policy '" + policy + "'",
    );
  }
  const floor = Number(cfg.hard_fail_below || 0);
  if (rate < floor) {
    if (cfg.hard_gate) {
      disq.push(
        "hire rate " +
          pctStr(rate) +
          " is below the " +
          pctStr(floor) +
          " floor",
      );
    }
    return crit(
      "hire_rate",
      0,
      weight,
      pctStr(rate) + " below " + pctStr(floor) + " floor",
    );
  }
  const share = ramp(
    rate,
    floor,
    Number(cfg.target === undefined ? 1 : cfg.target),
  );
  return crit("hire_rate", weight * share, weight, pctStr(rate) + " hire rate");
}

function cSpend(job, rub, weight, disq) {
  const cfg = rub.client_spend;
  const rawSpend = (job.client || {}).total_spend;
  if (rawSpend === null || rawSpend === undefined) {
    const policy = rub.unknown_client_policy || "neutral";
    if (policy === "disqualify") {
      disq.push("client spend unknown");
      return crit("client_spend", 0, weight, "spend unknown");
    }
    const share = policy === "penalize" ? 0 : 0.5;
    return crit(
      "client_spend",
      weight * share,
      weight,
      "spend unknown - policy '" + policy + "'",
    );
  }
  const spend = Number(rawSpend);
  const floor = Number(cfg.hard_fail_below_usd || 0);
  if (spend < floor) {
    if (cfg.hard_gate) {
      disq.push("client spend $" + money(spend) + " below $" + money(floor));
    }
    return crit("client_spend", 0, weight, "$" + money(spend) + " below floor");
  }
  const share = ramp(spend, floor, Number(cfg.target_usd || 1));
  return crit(
    "client_spend",
    weight * share,
    weight,
    "$" + money(spend) + " lifetime spend",
  );
}

function cPayment(job, rub, weight, disq) {
  const cfg = rub.payment_verified;
  const verified = (job.client || {}).payment_verified;
  if (verified === null || verified === undefined) {
    return crit(
      "payment_verified",
      weight * 0.5,
      weight,
      "verification status unknown",
    );
  }
  if (!verified) {
    if (cfg.required) disq.push("client payment method is not verified");
    return crit("payment_verified", 0, weight, "not verified");
  }
  return crit("payment_verified", weight, weight, "verified");
}

function cBudget(job, rub, weight, disq) {
  const cfg = rub.budget;
  const jobType = String(job.job_type || "fixed").toLowerCase();
  let rate;
  let floor;
  let target;
  let label;
  if (jobType === "hourly") {
    rate = job.hourly_max || job.hourly_min;
    floor = Number(cfg.hourly_floor_usd || 0);
    target = Number(cfg.hourly_target_usd || 1);
    label = "/hr";
  } else {
    rate = job.budget;
    floor = Number(cfg.fixed_floor_usd || 0);
    target = Number(cfg.fixed_target_usd || 1);
    label = " fixed";
  }
  if (rate === null || rate === undefined) {
    const policy = cfg.missing_budget_policy || "neutral";
    if (policy === "disqualify") {
      disq.push("job has no stated budget");
      return crit("budget", 0, weight, "no budget stated");
    }
    const share = policy === "penalize" ? 0 : 0.5;
    return crit(
      "budget",
      weight * share,
      weight,
      "no budget stated - policy '" + policy + "'",
    );
  }
  rate = Number(rate);
  if (rate < floor) {
    if (cfg.hard_gate) {
      disq.push(
        "$" + money(rate) + label + " is below the $" + money(floor) + " floor",
      );
    }
    return crit(
      "budget",
      0,
      weight,
      "$" + money(rate) + label + " below floor",
    );
  }
  const share = ramp(rate, floor, target);
  return crit("budget", weight * share, weight, "$" + money(rate) + label);
}

function cProposals(job, rub, weight) {
  const cfg = rub.proposals;
  const raw = job.proposals;
  if (raw === null || raw === undefined) {
    return crit("proposals", weight * 0.5, weight, "proposal count unknown");
  }
  const count = Number(raw);
  const ideal = Number(cfg.ideal_max === undefined ? 5 : cfg.ideal_max);
  const zeroAt = Number(cfg.zero_at === undefined ? 50 : cfg.zero_at);
  let share;
  if (count <= ideal) share = 1;
  else if (zeroAt <= ideal) share = 0;
  else share = clamp((zeroAt - count) / (zeroAt - ideal));
  return crit(
    "proposals",
    weight * share,
    weight,
    String(Math.trunc(count)) + " proposals so far",
  );
}

function cKeywords(job, rub, weight, disq) {
  const cfg = rub.keywords;
  const text = haystack(job);
  const banned = (cfg.must_not_have || []).filter(
    (k) => text.indexOf(String(k).toLowerCase()) !== -1,
  );
  if (banned.length) {
    if (cfg.hard_gate) disq.push("banned keyword: " + String(banned[0]));
    return crit(
      "keywords",
      0,
      weight,
      "banned keyword '" + String(banned[0]) + "'",
    );
  }
  const bonusHits = (cfg.bonus || []).filter(
    (k) => text.indexOf(String(k).toLowerCase()) !== -1,
  );
  const must = cfg.must_have_any || [];
  if (must.length) {
    const hits = must.filter(
      (k) => text.indexOf(String(k).toLowerCase()) !== -1,
    );
    if (!hits.length) {
      if (cfg.hard_gate) disq.push("no must-have keyword present");
      return crit("keywords", 0, weight, "no must-have keyword");
    }
    const base = weight * 0.7;
    const extra = weight * 0.3 * clamp(bonusHits.length / 3);
    return crit(
      "keywords",
      base + extra,
      weight,
      "must-have '" +
        String(hits[0]) +
        "' + " +
        bonusHits.length +
        " bonus term(s)",
    );
  }
  if (!bonusHits.length)
    return crit("keywords", 0, weight, "no matching keywords");
  const share = clamp(bonusHits.length / 3);
  return crit(
    "keywords",
    weight * share,
    weight,
    bonusHits.length +
      " bonus term(s): " +
      bonusHits.slice(0, 3).map(String).join(", "),
  );
}

function cFreshness(job, rub, weight, disq, now) {
  const cfg = rub.freshness;
  const posted = parseTs(job.posted_at);
  if (posted === null)
    return crit("freshness", weight * 0.5, weight, "post time unknown");
  let ageHours = (now.getTime() - posted.getTime()) / 3600000;
  if (ageHours < 0) ageHours = 0;
  const fresh = Number(cfg.fresh_hours === undefined ? 2 : cfg.fresh_hours);
  const stale = Number(cfg.stale_hours === undefined ? 48 : cfg.stale_hours);
  let share;
  if (ageHours <= fresh) share = 1;
  else if (stale <= fresh) share = 0;
  else share = clamp((stale - ageHours) / (stale - fresh));
  return crit(
    "freshness",
    weight * share,
    weight,
    "posted " + hours(ageHours) + "h ago",
  );
}

// -- public -----------------------------------------------------------------

function scoreJob(job, rubric, now) {
  const rub = mergeRubric(DEFAULT_RUBRIC, rubric);
  const when = now ? (now instanceof Date ? now : new Date(now)) : new Date();
  const weights = rub.weights || {};
  const disq = [];

  const handlers = [
    ["client_country", (w) => cCountry(job, rub, w, disq)],
    ["hire_rate", (w) => cHireRate(job, rub, w, disq)],
    ["client_spend", (w) => cSpend(job, rub, w, disq)],
    ["payment_verified", (w) => cPayment(job, rub, w, disq)],
    ["budget", (w) => cBudget(job, rub, w, disq)],
    ["proposals", (w) => cProposals(job, rub, w, disq)],
    ["keywords", (w) => cKeywords(job, rub, w, disq)],
    ["freshness", (w) => cFreshness(job, rub, w, disq, when)],
  ];

  const breakdown = [];
  let earned = 0;
  let possible = 0;
  handlers.forEach((pair) => {
    const weight = Number(weights[pair[0]] || 0);
    if (weight <= 0) return;
    const result = pair[1](weight);
    breakdown.push(result);
    earned += result.earned;
    possible += result.maximum;
  });

  const raw =
    possible <= 0 ? 0 : Math.trunc(roundHalfUp((earned / possible) * 100, 0));
  const score = disq.length ? 0 : raw;
  const threshold = Number(
    rub.alert_threshold === undefined ? 70 : rub.alert_threshold,
  );

  return {
    id: job.id === undefined ? null : job.id,
    title: job.title === undefined ? null : job.title,
    url: job.url === undefined ? null : job.url,
    score: score,
    raw_score: raw,
    threshold: threshold,
    disqualified: disq.length > 0,
    disqualifiers: disq,
    passed: disq.length === 0 && score >= threshold,
    breakdown: breakdown,
  };
}

function scoreJobs(jobs, rubric, now) {
  const results = (jobs || []).map((job) => scoreJob(job, rubric, now));
  results.sort((a, b) => b.score - a.score);
  return results;
}

if (typeof module !== "undefined" && module.exports) {
  module.exports = { DEFAULT_RUBRIC, scoreJob, scoreJobs, roundHalfUp };
}

/**
 * JS twin of scoring/caps.py - the three loop caps plus the circuit breaker.
 *
 * Embedded into the "Caps Preflight" and "Persist State" Code nodes of
 * workflows/upwork-job-radar.json by scripts/build_workflow.py. Edit here,
 * then rebuild - never edit the copy inside the workflow JSON.
 *
 * In n8n the state object lives in $getWorkflowStaticData('global').caps, so
 * it survives between executions, which is the whole point of a spend counter.
 *
 * tests/test_parity.py drives the same scripted sequence through both this
 * file and caps.py and fails if the resulting state differs.
 */

const DEFAULT_CAPS = {
  max_steps_per_run: 200,
  wall_clock_seconds: 120,
  spend: { cap_usd: 5.0, window_hours: 24 },
  circuit_breaker: {
    consecutive_errors: 3,
    cooldown_minutes: 60,
    auto_disable: true,
  },
};

class CapExceeded extends Error {
  constructor(cap, message) {
    super(message);
    this.name = "CapExceeded";
    this.cap = cap;
  }
}

class CircuitOpen extends CapExceeded {
  constructor(message) {
    super("circuit_breaker", message);
    this.name = "CircuitOpen";
  }
}

function mergeCaps(base, override) {
  const out = {};
  Object.keys(base).forEach((k) => {
    const v = base[k];
    out[k] =
      v && typeof v === "object" && !Array.isArray(v)
        ? Object.assign({}, v)
        : v;
  });
  if (!override) return out;
  Object.keys(override).forEach((k) => {
    const v = override[k];
    if (
      v &&
      typeof v === "object" &&
      !Array.isArray(v) &&
      out[k] &&
      typeof out[k] === "object" &&
      !Array.isArray(out[k])
    ) {
      out[k] = Object.assign({}, out[k], v);
    } else {
      out[k] = v;
    }
  });
  return out;
}

function parseDate(value) {
  if (value === null || value === undefined) return null;
  if (value instanceof Date) return isNaN(value.getTime()) ? null : value;
  let text = String(value);
  if (!/(Z|[+-]\d{2}:?\d{2})$/.test(text)) text += "Z";
  const ms = Date.parse(text);
  return isNaN(ms) ? null : new Date(ms);
}

function isoOf(date) {
  return date === null || date === undefined ? null : date.toISOString();
}

class CapsGuard {
  constructor(caps, state, nowFn) {
    this.caps = mergeCaps(DEFAULT_CAPS, caps);
    this.nowFn = nowFn || (() => new Date());
    const s = state || {};
    this.spendUsd = Number(s.spend_usd || 0);
    this.windowStart = parseDate(s.window_start) || this.nowFn();
    this.consecutiveErrors = Number(s.consecutive_errors || 0);
    this.disabled = Boolean(s.disabled);
    this.disabledReason =
      s.disabled_reason === undefined ? null : s.disabled_reason;
    this.disabledAt = parseDate(s.disabled_at);
    this.lastError = s.last_error === undefined ? null : s.last_error;
    this.totalRuns = Number(s.total_runs || 0);
    this.totalSteps = Number(s.total_steps || 0);
    this.halfOpen = Boolean(s.half_open);
    this.steps = 0;
    this.runStarted = null;
  }

  toDict() {
    return {
      spend_usd: Math.round(this.spendUsd * 1e6) / 1e6,
      window_start: isoOf(this.windowStart),
      consecutive_errors: this.consecutiveErrors,
      disabled: this.disabled,
      disabled_reason: this.disabledReason,
      disabled_at: isoOf(this.disabledAt),
      last_error: this.lastError,
      total_runs: this.totalRuns,
      total_steps: this.totalSteps,
      half_open: this.halfOpen,
    };
  }

  rollSpendWindow() {
    const windowHours = Number(
      this.caps.spend.window_hours === undefined
        ? 24
        : this.caps.spend.window_hours,
    );
    if (
      this.nowFn().getTime() - this.windowStart.getTime() >=
      windowHours * 3600000
    ) {
      this.spendUsd = 0;
      this.windowStart = this.nowFn();
    }
  }

  cooldownElapsed() {
    const minutes = Number(this.caps.circuit_breaker.cooldown_minutes || 0);
    if (!this.disabledAt || minutes <= 0) return false;
    return (
      this.nowFn().getTime() - this.disabledAt.getTime() >= minutes * 60000
    );
  }

  trip(reason) {
    this.disabled = true;
    this.disabledReason = reason;
    this.disabledAt = this.nowFn();
    this.halfOpen = false;
  }

  startRun() {
    if (this.disabled) {
      if (this.cooldownElapsed()) {
        this.disabled = false;
        this.halfOpen = true;
      } else {
        throw new CircuitOpen(
          "circuit breaker open: " + String(this.disabledReason),
        );
      }
    }
    this.rollSpendWindow();
    this.steps = 0;
    this.runStarted = this.nowFn();
    this.totalRuns += 1;
  }

  check(projectedCostUsd) {
    const projected = Number(projectedCostUsd || 0);
    if (this.disabled) {
      throw new CircuitOpen(
        "circuit breaker open: " + String(this.disabledReason),
      );
    }
    const maxSteps = Number(this.caps.max_steps_per_run || 0);
    if (maxSteps && this.steps >= maxSteps) {
      throw new CapExceeded(
        "max_steps_per_run",
        "step cap reached: " + this.steps + "/" + maxSteps,
      );
    }
    const wall = Number(this.caps.wall_clock_seconds || 0);
    if (wall && this.runStarted) {
      const elapsed =
        (this.nowFn().getTime() - this.runStarted.getTime()) / 1000;
      if (elapsed >= wall) {
        throw new CapExceeded(
          "wall_clock_seconds",
          "wall clock cap reached: " +
            elapsed.toFixed(1) +
            "s/" +
            wall.toFixed(0) +
            "s",
        );
      }
    }
    const capUsd = Number(this.caps.spend.cap_usd || 0);
    if (capUsd) {
      this.rollSpendWindow();
      if (this.spendUsd + projected > capUsd) {
        throw new CapExceeded(
          "spend",
          "spend cap reached: $" +
            (this.spendUsd + projected).toFixed(4) +
            "/$" +
            capUsd.toFixed(2) +
            " in the last " +
            this.caps.spend.window_hours +
            "h",
        );
      }
    }
  }

  recordStep(costUsd) {
    this.steps += 1;
    this.totalSteps += 1;
    const cost = Number(costUsd || 0);
    if (cost) {
      this.rollSpendWindow();
      this.spendUsd += cost;
    }
  }

  recordError(message) {
    this.consecutiveErrors += 1;
    this.lastError = message || null;
    const breaker = this.caps.circuit_breaker;
    if (breaker.auto_disable === false) return false;
    const limit = Number(breaker.consecutive_errors || 3);
    if (this.halfOpen) {
      this.trip("half-open probe failed: " + (message || "unknown error"));
      return true;
    }
    if (this.consecutiveErrors >= limit) {
      this.trip(
        this.consecutiveErrors +
          " consecutive errors (limit " +
          limit +
          "): " +
          (message || "unknown error"),
      );
      return true;
    }
    return false;
  }

  recordSuccess() {
    this.consecutiveErrors = 0;
    this.lastError = null;
    this.halfOpen = false;
  }

  reset() {
    this.disabled = false;
    this.disabledReason = null;
    this.disabledAt = null;
    this.consecutiveErrors = 0;
    this.halfOpen = false;
  }

  remaining() {
    this.rollSpendWindow();
    const elapsed = this.runStarted
      ? (this.nowFn().getTime() - this.runStarted.getTime()) / 1000
      : 0;
    return {
      steps_used: this.steps,
      steps_cap: Number(this.caps.max_steps_per_run || 0),
      seconds_used: Math.round(elapsed * 100) / 100,
      seconds_cap: Number(this.caps.wall_clock_seconds || 0),
      spend_used_usd: Math.round(this.spendUsd * 10000) / 10000,
      spend_cap_usd: Number(this.caps.spend.cap_usd || 0),
      spend_window_hours: this.caps.spend.window_hours,
      consecutive_errors: this.consecutiveErrors,
      disabled: this.disabled,
      disabled_reason: this.disabledReason,
      half_open: this.halfOpen,
    };
  }
}

if (typeof module !== "undefined" && module.exports) {
  module.exports = { DEFAULT_CAPS, CapsGuard, CapExceeded, CircuitOpen };
}

// --- n8n runner ---
// --- n8n runner: score every job, counting each one against the step cap ---
const staticData = $getWorkflowStaticData('global');
const items = $input.all();
if (!items.length) return [];

const cfg = $('Caps Preflight').first().json;
const guard = new CapsGuard(cfg.caps, staticData.caps);
// Re-anchor the wall clock to when this run actually started, not to now.
guard.runStarted = new Date(staticData.run_started_at || Date.now());

const out = [];
let stoppedBy = null;
for (const item of items) {
  try {
    guard.check(0);
  } catch (err) {
    stoppedBy = err.cap + ': ' + err.message;
    break;
  }
  const job = item.json.job;
  const result = scoreJob(job, item.json.rubric, new Date());
  guard.recordStep(0);
  out.push({ json: { job, result, stopped_by: null } });
}

staticData.caps = guard.toDict();
if (stoppedBy && out.length) out[0].json.stopped_by = stoppedBy;
if (stoppedBy && !out.length) return [{ json: { stopped_by: stoppedBy, result: null } }];
return out;

// Skip Already Alerted - one alert per job id, ever. Keeps the last 2000 ids
// in workflow static data so a restart does not re-spam the channel.
const staticData = $getWorkflowStaticData('global');
staticData.seen = Array.isArray(staticData.seen) ? staticData.seen : [];
const seen = new Set(staticData.seen);

const fresh = [];
for (const item of $input.all()) {
  const id = item.json.result && item.json.result.id;
  if (!id || seen.has(id)) continue;
  seen.add(id);
  fresh.push(item);
}

staticData.seen = Array.from(seen).slice(-2000);
return fresh;

// Format Slack Alert - mirrors scoring/slack.py build_slack_blocks().
// The draft opener is a template, not a model call, so a default install
// spends nothing. Swap in an LLM node here if you want richer drafts - that
// is exactly what the spend cap in Caps Preflight is protecting.
const BAR = 10;
const bar = (earned, maximum) => {
  if (maximum <= 0) return ' '.repeat(BAR);
  const filled = Math.round(BAR * Math.max(0, Math.min(1, earned / maximum)));
  return '#'.repeat(filled) + '.'.repeat(BAR - filled);
};
const money = (v) => (v === null || v === undefined || isNaN(Number(v))
  ? 'n/a'
  : '$' + String(Math.round(Number(v))).replace(/\B(?=(\d{3})+(?!\d))/g, ','));
const budgetLine = (job) => {
  if (String(job.job_type || 'fixed').toLowerCase() === 'hourly') {
    if (job.hourly_min && job.hourly_max) {
      return money(job.hourly_min) + '-' + money(job.hourly_max) + '/hr';
    }
    if (job.hourly_max || job.hourly_min) return money(job.hourly_max || job.hourly_min) + '/hr';
    return 'hourly, rate not stated';
  }
  return job.budget ? money(job.budget) + ' fixed' : 'budget not stated';
};
const draftOpener = (job, result) => {
  const skills = (job.skills || []).slice(0, 3).map(String);
  const skillsTxt = skills.length ? skills.join(', ') : 'the stack you listed';
  const ranked = (result.breakdown || []).filter((b) => b.maximum > 0)
    .sort((a, b) => (b.earned / b.maximum) - (a.earned / a.maximum));
  const angle = ranked.length ? ranked[0].reason : 'the brief';
  return 'Hi - on "' + String(job.title || 'your project').trim() + '": the part I would '
    + 'start with is ' + skillsTxt + ', because that is where this scope usually stalls.\n'
    + 'Two questions before I quote: what does done look like for you, and who owns the '
    + 'accounts/credentials?\nSignal I picked up from the post: ' + angle + '.';
};

return $input.all().map((item) => {
  const job = item.json.job;
  const result = item.json.result;
  const client = job.client || {};
  const lines = (result.breakdown || []).map((b) => '`' + b.key + '` '
    + bar(b.earned, b.maximum) + ' ' + b.earned + '/' + Math.round(b.maximum)
    + ' - ' + b.reason);
  const blocks = [
    { type: 'header',
      text: { type: 'plain_text', text: 'Score ' + result.score + ' - ' + String(job.title || '').slice(0, 120) } },
    { type: 'section',
      fields: [
        { type: 'mrkdwn', text: '*Budget*\n' + budgetLine(job) },
        { type: 'mrkdwn', text: '*Country*\n' + (client.country || 'unknown') },
        { type: 'mrkdwn', text: '*Proposals*\n' + (job.proposals === null || job.proposals === undefined ? 'unknown' : job.proposals) },
        { type: 'mrkdwn', text: '*Client spend*\n' + money(client.total_spend) },
      ] },
    { type: 'section', text: { type: 'mrkdwn', text: '*Why it scored this*\n' + lines.join('\n') } },
    { type: 'section', text: { type: 'mrkdwn', text: '*Draft opener (yours to edit - nothing was sent)*\n>' + draftOpener(job, result).replace(/\n/g, '\n>') } },
    { type: 'context', elements: [{ type: 'mrkdwn',
      text: 'Read-only alert. Nothing was submitted to Upwork. <' + (job.url || 'https://www.upwork.com') + '|Open the job> and apply by hand.' }] },
  ];
  return { json: { text: 'Upwork Job Radar: ' + String(job.title || '').slice(0, 80) + ' scored ' + result.score, blocks } };
});

