  }

  check(projectedCostUsd) {
    const projected = Number(projectedCostUsd || 0);
    if (this.disabled) {
      throw new CircuitOpen(
        "circuit breaker open: " + String(this.disabledReason),
      );
    }
    const maxSteps = Number(this.caps.max_steps_per_run || 0);
    if (maxSteps && this.steps >= maxSteps) {
      throw new CapExceeded(
        "max_steps_per_run",
        "step cap reached: " + this.steps + "/" + maxSteps,
      );
    }
    const wall = Number(this.caps.wall_clock_seconds || 0);
    if (wall && this.runStarted) {
      const elapsed =
        (this.nowFn().getTime() - this.runStarted.getTime()) / 1000;
      if (elapsed >= wall) {
        throw new CapExceeded(
          "wall_clock_seconds",
          "wall clock cap reached: " +
            elapsed.toFixed(1) +
            "s/" +
            wall.toFixed(0) +
            "s",
        );
      }
    }
    const capUsd = Number(this.caps.spend.cap_usd || 0);
    if (capUsd) {
      this.rollSpendWindow();
      if (this.spendUsd + projected > capUsd) {
        throw new CapExceeded(
          "spend",
          "spend cap reached: $" +
            (this.spendUsd + projected).toFixed(4) +
            "/$" +
            capUsd.toFixed(2) +
            " in the last " +
            this.caps.spend.window_hours +
            "h",
        );
      }
    }
  }

  recordStep(costUsd) {
    this.steps += 1;
    this.totalSteps += 1;
    const cost = Number(costUsd || 0);
    if (cost) {
      this.rollSpendWindow();
      this.spendUsd += cost;
    }
  }

  recordError(message) {
    this.consecutiveErrors += 1;
    this.lastError = message || null;
    const breaker = this.caps.circuit_breaker;
    if (breaker.auto_disable === false) return false;
    const limit = Number(breaker.consecutive_errors || 3);
    if (this.halfOpen) {
      this.trip("half-open probe failed: " + (message || "unknown error"));
      return true;
    }
    if (this.consecutiveErrors >= limit) {
      this.trip(
        this.consecutiveErrors +
          " consecutive errors (limit " +
          limit +
          "): " +
          (message || "unknown error"),
      );
      return true;
    }
    return false;
  }

  recordSuccess() {
    this.consecutiveErrors = 0;
    this.lastError = null;
    this.halfOpen = false;
  }

  reset() {
    this.disabled = false;
    this.disabledReason = null;
    this.disabledAt = null;
    this.consecutiveErrors = 0;
    this.halfOpen = false;
  }

  remaining() {
    this.rollSpendWindow();
    const elapsed = this.runStarted
      ? (this.nowFn().getTime() - this.runStarted.getTime()) / 1000
      : 0;
    return {
      steps_used: this.steps,
      steps_cap: Number(this.caps.max_steps_per_run || 0),
      seconds_used: Math.round(elapsed * 100) / 100,
      seconds_cap: Number(this.caps.wall_clock_seconds || 0),
      spend_used_usd: Math.round(this.spendUsd * 10000) / 10000,
      spend_cap_usd: Number(this.caps.spend.cap_usd || 0),
      spend_window_hours: this.caps.spend.window_hours,
      consecutive_errors: this.consecutiveErrors,
      disabled: this.disabled,
      disabled_reason: this.disabledReason,
      half_open: this.halfOpen,
    };
  }
}

if (typeof module !== "undefined" && module.exports) {
  module.exports = { DEFAULT_CAPS, CapsGuard, CapExceeded, CircuitOpen };
}

// --- n8n runner ---
// Persist State - close the run out cleanly: clear the error streak, roll the
// spend counter forward, and keep a small history for the daily digest.
const staticData = $getWorkflowStaticData('global');
const cfg = $('Caps Preflight').first().json;
const guard = new CapsGuard(cfg.caps, staticData.caps);
guard.recordSuccess();
staticData.caps = guard.toDict();

staticData.history = Array.isArray(staticData.history) ? staticData.history : [];
for (const item of $input.all()) {
  staticData.history.push({
    at: new Date().toISOString(),
    id: item.json.result ? item.json.result.id : null,
    score: item.json.result ? item.json.result.score : null,
    title: item.json.result ? item.json.result.title : null,
    passed: item.json.result ? item.json.result.passed : null,
    disqualifiers: item.json.result ? item.json.result.disqualifiers : [],
  });
}
staticData.history = staticData.history.slice(-500);

return [{ json: { alerted: $input.all().length, caps: guard.remaining() } }];

/**
 * JS twin of scoring/caps.py - the three loop caps plus the circuit breaker.
 *
 * Embedded into the "Caps Preflight" and "Persist State" Code nodes of
 * workflows/upwork-job-radar.json by scripts/build_workflow.py. Edit here,
 * then rebuild - never edit the copy inside the workflow JSON.
 *
 * In n8n the state object lives in $getWorkflowStaticData('global').caps, so
 * it survives between executions, which is the whole point of a spend counter.
 *
 * tests/test_parity.py drives the same scripted sequence through both this
 * file and caps.py and fails if the resulting state differs.
 */

const DEFAULT_CAPS = {
  max_steps_per_run: 200,
  wall_clock_seconds: 120,
  spend: { cap_usd: 5.0, window_hours: 24 },
  circuit_breaker: {
    consecutive_errors: 3,
    cooldown_minutes: 60,
    auto_disable: true,
  },
};

class CapExceeded extends Error {
  constructor(cap, message) {
    super(message);
    this.name = "CapExceeded";
    this.cap = cap;
  }
}

class CircuitOpen extends CapExceeded {
  constructor(message) {
    super("circuit_breaker", message);
    this.name = "CircuitOpen";
  }
}

function mergeCaps(base, override) {
  const out = {};
  Object.keys(base).forEach((k) => {
    const v = base[k];
    out[k] =
      v && typeof v === "object" && !Array.isArray(v)
        ? Object.assign({}, v)
        : v;
  });
  if (!override) return out;
  Object.keys(override).forEach((k) => {
    const v = override[k];
    if (
      v &&
      typeof v === "object" &&
      !Array.isArray(v) &&
      out[k] &&
      typeof out[k] === "object" &&
      !Array.isArray(out[k])
    ) {
      out[k] = Object.assign({}, out[k], v);
    } else {
      out[k] = v;
    }
  });
  return out;
}

function parseDate(value) {
  if (value === null || value === undefined) return null;
  if (value instanceof Date) return isNaN(value.getTime()) ? null : value;
  let text = String(value);
  if (!/(Z|[+-]\d{2}:?\d{2})$/.test(text)) text += "Z";
  const ms = Date.parse(text);
  return isNaN(ms) ? null : new Date(ms);
}

function isoOf(date) {
  return date === null || date === undefined ? null : date.toISOString();
}

class CapsGuard {
  constructor(caps, state, nowFn) {
    this.caps = mergeCaps(DEFAULT_CAPS, caps);
    this.nowFn = nowFn || (() => new Date());
    const s = state || {};
    this.spendUsd = Number(s.spend_usd || 0);
    this.windowStart = parseDate(s.window_start) || this.nowFn();
    this.consecutiveErrors = Number(s.consecutive_errors || 0);
    this.disabled = Boolean(s.disabled);
    this.disabledReason =
      s.disabled_reason === undefined ? null : s.disabled_reason;
    this.disabledAt = parseDate(s.disabled_at);
    this.lastError = s.last_error === undefined ? null : s.last_error;
    this.totalRuns = Number(s.total_runs || 0);
    this.totalSteps = Number(s.total_steps || 0);
    this.halfOpen = Boolean(s.half_open);
    this.steps = 0;
    this.runStarted = null;
  }

  toDict() {
    return {
      spend_usd: Math.round(this.spendUsd * 1e6) / 1e6,
      window_start: isoOf(this.windowStart),
      consecutive_errors: this.consecutiveErrors,
      disabled: this.disabled,
      disabled_reason: this.disabledReason,
      disabled_at: isoOf(this.disabledAt),
      last_error: this.lastError,
      total_runs: this.totalRuns,
      total_steps: this.totalSteps,
      half_open: this.halfOpen,
    };
  }

  rollSpendWindow() {
    const windowHours = Number(
      this.caps.spend.window_hours === undefined
        ? 24
        : this.caps.spend.window_hours,
    );
    if (
      this.nowFn().getTime() - this.windowStart.getTime() >=
      windowHours * 3600000
    ) {
      this.spendUsd = 0;
      this.windowStart = this.nowFn();
    }
  }

  cooldownElapsed() {
    const minutes = Number(this.caps.circuit_breaker.cooldown_minutes || 0);
    if (!this.disabledAt || minutes <= 0) return false;
    return (
      this.nowFn().getTime() - this.disabledAt.getTime() >= minutes * 60000
    );
  }

  trip(reason) {
    this.disabled = true;
    this.disabledReason = reason;
    this.disabledAt = this.nowFn();
    this.halfOpen = false;
  }

  startRun() {
    if (this.disabled) {
      if (this.cooldownElapsed()) {
        this.disabled = false;
        this.halfOpen = true;
      } else {
        throw new CircuitOpen(
          "circuit breaker open: " + String(this.disabledReason),
        );
      }
    }
    this.rollSpendWindow();
    this.steps = 0;
    this.runStarted = this.nowFn();
    this.totalRuns += 1;
  }

  check(projectedCostUsd) {
    const projected = Number(projectedCostUsd || 0);
    if (this.disabled) {
      throw new CircuitOpen(
        "circuit breaker open: " + String(this.disabledReason),
      );
    }
    const maxSteps = Number(this.caps.max_steps_per_run || 0);
    if (maxSteps && this.steps >= maxSteps) {
      throw new CapExceeded(
        "max_steps_per_run",
        "step cap reached: " + this.steps + "/" + maxSteps,
      );
    }
    const wall = Number(this.caps.wall_clock_seconds || 0);
    if (wall && this.runStarted) {
      const elapsed =
        (this.nowFn().getTime() - this.runStarted.getTime()) / 1000;
      if (elapsed >= wall) {
        throw new CapExceeded(
          "wall_clock_seconds",
          "wall clock cap reached: " +
            elapsed.toFixed(1) +
            "s/" +
            wall.toFixed(0) +
            "s",
        );
      }
    }
    const capUsd = Number(this.caps.spend.cap_usd || 0);
    if (capUsd) {
      this.rollSpendWindow();
      if (this.spendUsd + projected > capUsd) {
        throw new CapExceeded(
          "spend",
          "spend cap reached: $" +
            (this.spendUsd + projected).toFixed(4) +
            "/$" +
            capUsd.toFixed(2) +
            " in the last " +
            this.caps.spend.window_hours +
            "h",
        );
      }
    }
  }

  recordStep(costUsd) {
    this.steps += 1;
    this.totalSteps += 1;
    const cost = Number(costUsd || 0);
    if (cost) {
      this.rollSpendWindow();
      this.spendUsd += cost;
    }
  }

  recordError(message) {
    this.consecutiveErrors += 1;
    this.lastError = message || null;
    const breaker = this.caps.circuit_breaker;
    if (breaker.auto_disable === false) return false;
    const limit = Number(breaker.consecutive_errors || 3);
    if (this.halfOpen) {
      this.trip("half-open probe failed: " + (message || "unknown error"));
      return true;
    }
    if (this.consecutiveErrors >= limit) {
      this.trip(
        this.consecutiveErrors +
          " consecutive errors (limit " +
          limit +
          "): " +
          (message || "unknown error"),
      );
      return true;
    }
    return false;
  }

  recordSuccess() {
    this.consecutiveErrors = 0;
    this.lastError = null;
    this.halfOpen = false;
  }

  reset() {
    this.disabled = false;
    this.disabledReason = null;
    this.disabledAt = null;
    this.consecutiveErrors = 0;
    this.halfOpen = false;
  }

  remaining() {
    this.rollSpendWindow();
    const elapsed = this.runStarted
      ? (this.nowFn().getTime() - this.runStarted.getTime()) / 1000
      : 0;
    return {
      steps_used: this.steps,
      steps_cap: Number(this.caps.max_steps_per_run || 0),
      seconds_used: Math.round(elapsed * 100) / 100,
      seconds_cap: Number(this.caps.wall_clock_seconds || 0),
      spend_used_usd: Math.round(this.spendUsd * 10000) / 10000,
      spend_cap_usd: Number(this.caps.spend.cap_usd || 0),
      spend_window_hours: this.caps.spend.window_hours,
      consecutive_errors: this.consecutiveErrors,
      disabled: this.disabled,
      disabled_reason: this.disabledReason,
      half_open: this.halfOpen,
    };
  }
}

if (typeof module !== "undefined" && module.exports) {
  module.exports = { DEFAULT_CAPS, CapsGuard, CapExceeded, CircuitOpen };
}

// --- n8n runner ---
// --- n8n runner: breaker alert --------------------------------------------
// Reached from two places, and they mean opposite things:
//
//   a) Caps Preflight said blocked=true. The guard already refused this run;
//      counting it again would let a tripped breaker inflate its own counter.
//   b) The Upwork call errored (onError: continueErrorOutput). THAT is a real
//      failure and it is the only thing that advances the error streak.
//
// Without this node calling recordError(), the breaker could never trip in
// production no matter how many times the API fell over.
const staticData = $getWorkflowStaticData('global');
const cfg = $input.first().json;
const preflight = $('Caps Preflight').first().json;
const wasRefusedByCaps = cfg.blocked === true;

let state = cfg.caps_state || preflight.caps_state || {};
let cap = cfg.blocked_cap || null;
let reason = cfg.blocked_reason || null;

if (!wasRefusedByCaps) {
  const guard = new CapsGuard(preflight.caps, staticData.caps);
  const message = (cfg.error && (cfg.error.message || cfg.error))
    || 'Upwork API request failed';
  const tripped = guard.recordError(String(message));
  staticData.caps = guard.toDict();
  state = guard.toDict();
  cap = tripped ? 'circuit_breaker' : 'upstream_error';
  reason = tripped
    ? guard.disabledReason
    : String(message) + ' (' + guard.consecutiveErrors + ' consecutive)';
}

return [{
  json: {
    text: 'Upwork Job Radar halted: ' + (reason || 'unknown reason'),
    blocks: [
      { type: 'header', text: { type: 'plain_text', text: 'Job Radar halted - ' + (cap || 'cap') } },
      { type: 'section', text: { type: 'mrkdwn', text: '*Reason*\n' + (reason || 'unknown') } },
      { type: 'section', fields: [
        { type: 'mrkdwn', text: '*Consecutive errors*\n' + (state.consecutive_errors || 0) },
        { type: 'mrkdwn', text: '*Spend this window*\n$' + Number(state.spend_usd || 0).toFixed(4) },
        { type: 'mrkdwn', text: '*Breaker*\n' + (state.disabled ? 'OPEN - workflow disabled' : 'closed') },
      ] },
      { type: 'context', elements: [{ type: 'mrkdwn',
        text: state.disabled
          ? 'The workflow disabled itself. It allows one probe run after the cooldown; fix the cause, or reset it by clearing `caps` in workflow static data.'
          : 'Counted against the error streak. The breaker opens once the streak reaches the configured limit.' }] },
    ],
  },
}];

// Build Digest - a once-a-day summary from the history the runs persisted.
// Mirrors scoring/slack.py render_digest().
const staticData = $getWorkflowStaticData('global');
const history = Array.isArray(staticData.history) ? staticData.history : [];
const since = Date.now() - 24 * 3600 * 1000;
const window = history.filter((h) => Date.parse(h.at) >= since);
const passed = window.filter((h) => h.passed);
const disq = window.filter((h) => (h.disqualifiers || []).length);

const counts = {};
disq.forEach((h) => (h.disqualifiers || []).forEach((d) => {
  const key = String(d).split(':')[0];
  counts[key] = (counts[key] || 0) + 1;
}));
const topReasons = Object.keys(counts).sort((a, b) => counts[b] - counts[a]).slice(0, 5);

const caps = staticData.caps || {};
const lines = [
  '*' + window.length + '* scored | *' + passed.length + '* passed | *' + disq.length + '* disqualified',
  passed.length
    ? passed.slice(0, 10).map((h) => '`' + h.score + '`  ' + String(h.title || '').slice(0, 56)).join('\n')
    : '_Nothing passed today. That is a normal day, not a broken radar._',
];
if (topReasons.length) {
  lines.push('*Top disqualifier reasons*\n'
    + topReasons.map((r) => '`' + counts[r] + 'x`  ' + r).join('\n'));
}
lines.push('_caps: $' + Number(caps.spend_usd || 0).toFixed(4) + ' spent this window | breaker '
  + (caps.disabled ? 'OPEN (disabled)' : 'closed') + '_');

return [{
  json: {
    text: 'Upwork Job Radar daily digest',
    blocks: [
      { type: 'header', text: { type: 'plain_text', text: 'Job Radar - last 24h' } },
      { type: 'section', text: { type: 'mrkdwn', text: lines.join('\n\n') } },
      { type: 'context', elements: [{ type: 'mrkdwn',
        text: 'Read-only. No proposal was submitted and no Connect was spent.' }] },
    ],
  },
}];
